      // (id + status + links ONLY — no purchase_units, no payment_source). Every
      // caller of this function needs the full order back, so this must always be
      // requested explicitly. See capturePayPalOrder's identical header for why.
      headers: { Prefer: "return=representation" },
      body: JSON.stringify(buildOrderBody({ ...opts, vault })),
    });
  if (!opts.vault) return create("", false);
  try {
    return await create("", true);
  } catch (e) {
    // Vaulting is documented as best-effort ("PayPal may decline to vault...
    // without failing the underlying payment" — see this function's doc
    // comment above), but PayPal actually rejects the whole ORDER CREATE, not
    // just the vault attempt, when the merchant account isn't Vault-API
    // enabled — so without this retry every payment would fail outright
    // whenever vaulting isn't available, instead of just not being saved for
    // future off-session renewal charges. A distinct idempotency-key suffix
    // avoids PayPal treating this as a replay of the first (differently-shaped,
    // failed) request.
    if (!isVaultRejection(e)) throw e;
    console.error("[paypal] account not vault-enabled — retrying without vaulting", e);
    return create("_novault", false);
  }
}

/**
 * Capture a PayPal order server-to-server. This — not anything the browser's
 * `onApprove` callback reports — is the authoritative "did the money move"
 * answer. Idempotent: PayPal returns the existing capture on a repeated call for
 * an order already captured (COMPLETED), so the client-driven capture and the
 * webhook backstop can race safely, exactly like the Stripe confirm/webhook race.
