cat > services/modbuilder/version.js <<'E'
"use strict";
// Plugin version rules for change builds. A refinement must never ship under the version of the build it refines:
// the installer compares versions, so a same-version jar was reported "already installed" and the change never
// reached the server (owner test 2026-10-13, Ruby Sword refined to purple). Pure, no I/O.
function parse(v) {
  const m = /^v?(\d+)(?:\.(\d+))?(?:\.(\d+))?/.exec(String(v == null ? "" : v).trim());
  return m ? [Number(m[1]), Number(m[2] || 0), Number(m[3] || 0)] : null;
}
function cmp(a, b) {
  for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] > b[i] ? 1 : -1;
  return 0;
}
/** The version a change build ships under: the model's own choice when it is already higher than the base, else base patch + 1. */
function bumpVersion(base, cur) {
  const b = parse(base);
  if (!b) return String(cur == null ? "" : cur);
  const c = parse(cur);
  if (c && cmp(c, b) > 0) return String(cur);
  return `${b[0]}.${b[1]}.${b[2] + 1}`;
}
module.exports = { parse, cmp, bumpVersion };
E
